import fs from 'fs/promises';
import path from 'path';
import { z } from 'zod';
import {
  GUIDANCE_REFERENCE_COUNT,
  GUIDANCE_REFERENCE_FILE_BYTES,
  GUIDANCE_REFERENCE_FILE_COUNT,
  GUIDANCE_REFERENCE_TOTAL_BYTES,
  GuidanceReferenceNameSchema,
  GuidanceRemoteReferenceUploadSchema,
  GuidanceDirectoryReferenceSchema,
  GuidanceDirectoryPathSchema,
  GuidanceReferencesUploadSchema,
} from '../../types/guidance-references';

const ManifestSchema = z
  .array(
    z.discriminatedUnion('kind', [
      GuidanceDirectoryReferenceSchema.extend({
        path: GuidanceDirectoryPathSchema,
      }),
      GuidanceRemoteReferenceUploadSchema.omit({ files: true }).extend({
        files: z
          .array(
            z
              .object({
                name: GuidanceReferenceNameSchema,
                path: z.string().min(1),
              })
              .strict(),
          )
          .max(GUIDANCE_REFERENCE_FILE_COUNT)
          .optional(),
      }),
    ]),
  )
  .max(GUIDANCE_REFERENCE_COUNT);

export const readGuidanceText = async (file: string): Promise<string> => {
  const metadata = await fs.lstat(file);
  if (
    !metadata.isFile() ||
    metadata.isSymbolicLink() ||
    metadata.size > GUIDANCE_REFERENCE_FILE_BYTES
  )
    throw new Error(
      `Reference input must be a regular file of at most 1 MiB: ${file}`,
    );
  const bytes = await fs.readFile(file);
  if (bytes.length > GUIDANCE_REFERENCE_FILE_BYTES)
    throw new Error(`Reference input exceeds 1 MiB: ${file}`);
  return new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(
    bytes,
  );
};

export const guidanceReferences = async (manifestPath: string) => {
  const manifest = ManifestSchema.parse(
    JSON.parse(await readGuidanceText(manifestPath)),
  );
  const references = [];
  let totalBytes = 0;
  let fileCount = 0;
  for (const reference of manifest) {
    if (reference.kind === 'directory') {
      const location = path.resolve(path.dirname(manifestPath), reference.path);
      try {
        const directory = await fs.realpath(location);
        if (!(await fs.stat(directory)).isDirectory())
          throw new Error('Not a directory');
        await fs.access(directory, fs.constants.R_OK | fs.constants.X_OK);
        const handle = await fs.opendir(directory);
        await handle.close();
        references.push({ ...reference, path: directory });
      } catch {
        throw new Error(
          `Reference path must be an existing, accessible directory: ${location}`,
        );
      }
      continue;
    }
    const files = [];
    for (const file of reference.files ?? []) {
      const content = await readGuidanceText(
        path.resolve(path.dirname(manifestPath), file.path),
      );
      totalBytes += Buffer.byteLength(content);
      fileCount++;
      if (
        totalBytes > GUIDANCE_REFERENCE_TOTAL_BYTES ||
        fileCount > GUIDANCE_REFERENCE_FILE_COUNT
      )
        throw new Error('Reference inputs exceed the 5 MiB or 100-file budget');
      files.push({ name: file.name, content });
    }
    references.push({ ...reference, ...(reference.files ? { files } : {}) });
  }
  return GuidanceReferencesUploadSchema.parse(references);
};
